@preconcurrency import CoreBluetooth
import Foundation

public final class CoreBluetoothTransport: NSObject, WearfitBLEExternalPeripheralTransport, @unchecked Sendable {
    private final class PeripheralSlot: @unchecked Sendable {
        let peripheral: CBPeripheral
        let sessionID: WearfitSessionID
        let token: ConnectionToken
        let eventStream = WearfitBLEEventStream()
        let lifecycle = TransportSessionLifecycle()
        let rawDataContinuation: AsyncStream<Data>.Continuation
        let rawDataStream: AsyncStream<Data>
        let connectOptions: WearfitConnectOptions
        let pendingConnection = PendingTransportConnection<WearfitBLETransportSession>()
        var session: CoreBluetoothPeripheralSession?
        var timeoutTask: Task<Void, Never>?

        init(
            peripheral: CBPeripheral,
            sessionID: WearfitSessionID,
            generation: UInt,
            connectOptions: WearfitConnectOptions
        ) {
            self.peripheral = peripheral
            self.sessionID = sessionID
            self.token = ConnectionToken(
                peripheralID: peripheral.identifier,
                sessionID: sessionID,
                generation: generation
            )
            self.connectOptions = connectOptions
            var continuation: AsyncStream<Data>.Continuation!
            self.rawDataStream = AsyncStream { continuation = $0 }
            self.rawDataContinuation = continuation
        }
    }

    private let serviceConfiguration: BLEServiceConfiguration
    private let advertisementParser: BLEAdvertisementParser
    private let queue: DispatchQueue
    private let packetizer: BLEPacketizer
    private let logger: WearfitBLELogger
    private let eventStream: WearfitBLEEventStream
    private let reconnectQuarantine: TimeInterval

    private var centralManager: CBCentralManager?
    private var centralStateContinuation: CheckedContinuation<Void, Error>?
    private var scanContinuation: AsyncThrowingStream<WearfitBLEDevice, Error>.Continuation?
    private var scanTimeoutTask: Task<Void, Never>?
    private var activeScanOptions: WearfitScanOptions?
    private var discoveredPeripherals: [UUID: CBPeripheral] = [:]
    private var peripheralSlots: [UUID: PeripheralSlot] = [:]
    private var nextGenerationByPeripheralID: [UUID: UInt] = [:]
    private var reconnectBarriers: [UUID: PeripheralReconnectBarrier] = [:]
    private var manualDisconnectIDs: Set<UUID> = []

    private let rawDataContinuation: AsyncStream<Data>.Continuation
    public let rawDataStream: AsyncStream<Data>

    public var events: AsyncStream<WearfitBLEEvent> {
        eventStream.stream
    }

    public init(
        serviceConfiguration: BLEServiceConfiguration = .nordicUART,
        advertisementParser: BLEAdvertisementParser = BLEAdvertisementParser(),
        packetizer: BLEPacketizer = BLEPacketizer(),
        logger: WearfitBLELogger = NoopWearfitBLELogger(),
        eventStream: WearfitBLEEventStream = WearfitBLEEventStream(),
        queue: DispatchQueue = DispatchQueue(label: "com.wearfit.blekit.central"),
        reconnectQuarantine: TimeInterval = 1
    ) {
        self.serviceConfiguration = serviceConfiguration
        self.advertisementParser = advertisementParser
        self.packetizer = packetizer
        self.logger = logger
        self.eventStream = eventStream
        self.queue = queue
        self.reconnectQuarantine = max(0, reconnectQuarantine)
        var capturedContinuation: AsyncStream<Data>.Continuation!
        self.rawDataStream = AsyncStream { continuation in
            capturedContinuation = continuation
        }
        self.rawDataContinuation = capturedContinuation
        super.init()
    }

    public func scan(options: WearfitScanOptions) -> AsyncThrowingStream<WearfitBLEDevice, Error> {
        AsyncThrowingStream { continuation in
            queue.async {
                self.scanContinuation = continuation
                self.ensureCentralManager()
                self.logger.log(.info, "scan requested")

                guard let centralManager = self.centralManager else {
                    continuation.finish(throwing: WearfitBLEError.bluetoothUnavailable)
                    return
                }

                guard centralManager.state == .poweredOn else {
                    return
                }

                self.startScan(options: options)
            }

            continuation.onTermination = { _ in
                self.stopScan()
            }
        }
    }

    public func stopScan() {
        queue.async {
            self.scanTimeoutTask?.cancel()
            self.scanTimeoutTask = nil
            self.centralManager?.stopScan()
            self.scanContinuation?.finish()
            self.scanContinuation = nil
            self.activeScanOptions = nil
        }
    }

    public func connect(
        _ device: WearfitBLEDevice,
        options: WearfitConnectOptions
    ) async throws -> BLECommandExecutor {
        try await connectSession(device, options: options).executor
    }

    public func connectSession(
        _ device: WearfitBLEDevice,
        options: WearfitConnectOptions
    ) async throws -> WearfitBLETransportSession {
        try await ensurePoweredOn()

        return try await withCheckedThrowingContinuation { continuation in
            queue.async {
                guard let peripheral = self.discoveredPeripherals[device.id] else {
                    continuation.resume(throwing: WearfitBLEError.invalidAdvertisement)
                    return
                }

                let barrier = self.reconnectBarrier(for: device.id)
                if let supersededSlot = self.peripheralSlots[device.id] {
                    self.retire(supersededSlot)
                    self.peripheralSlots.removeValue(forKey: device.id)
                    self.enterQuarantine(for: supersededSlot)
                    self.centralManager?.cancelPeripheralConnection(supersededSlot.peripheral)
                    continuation.resume(throwing: WearfitBLEError.reconnectCoolingDown)
                    return
                }
                guard barrier.allowsNewSlot() else {
                    continuation.resume(throwing: WearfitBLEError.reconnectCoolingDown)
                    return
                }
                let generation = self.nextGenerationByPeripheralID[device.id, default: 0]
                self.nextGenerationByPeripheralID[device.id] = generation &+ 1
                self.startConnection(
                    device: device,
                    peripheral: peripheral,
                    generation: generation,
                    options: options,
                    continuation: continuation
                )
            }
        }
    }

    public func connectSession(
        external peripheral: WearfitExternalPeripheral,
        options: WearfitConnectOptions
    ) async throws -> WearfitBLETransportSession {
        try await ensurePoweredOn()

        let device = peripheral.makeDevice()
        return try await withCheckedThrowingContinuation { continuation in
            queue.async {
                guard let cbPeripheral = self.resolvePeripheral(for: peripheral) else {
                    continuation.resume(throwing: WearfitBLEError.deviceNotFound)
                    return
                }

                self.discoveredPeripherals[device.id] = cbPeripheral
                Task {
                    do {
                        let session = try await self.connectSession(device, options: options)
                        continuation.resume(returning: session)
                    } catch {
                        continuation.resume(throwing: error)
                    }
                }
            }
        }
    }

    private func startConnection(
        device: WearfitBLEDevice,
        peripheral: CBPeripheral,
        generation: UInt,
        options: WearfitConnectOptions,
        continuation: CheckedContinuation<WearfitBLETransportSession, Error>
    ) {
                let slot = PeripheralSlot(
                    peripheral: peripheral,
                    sessionID: self.sessionID(for: device),
                    generation: generation,
                    connectOptions: options
                )
                self.peripheralSlots[device.id] = slot
                self.reconnectBarrier(for: device.id).activate(slot.token)
                slot.pendingConnection.install(continuation)
                self.manualDisconnectIDs.remove(device.id)
                slot.eventStream.emit(.connectionStateChanged(.connecting(sessionID: slot.sessionID)))
                self.centralManager?.connect(
                    peripheral,
                    options: self.connectOptions(for: options)
                )

                slot.timeoutTask = Task { [weak self] in
                    try? await Task.sleep(nanoseconds: UInt64(options.timeout * 1_000_000_000))
                    guard let self else { return }
                    queue.async {
                        guard let currentSlot = self.peripheralSlots[device.id],
                              currentSlot.token == slot.token else {
                            return
                        }
                        guard currentSlot.pendingConnection.resume(
                            throwing: WearfitBLEError.connectTimedOut
                        ) else {
                            return
                        }
                        currentSlot.lifecycle.finish(error: WearfitBLEError.connectTimedOut)
                        currentSlot.eventStream.emit(.connectionStateChanged(.disconnected(
                            sessionID: currentSlot.sessionID,
                            reason: .timeout
                        )))
                        currentSlot.rawDataContinuation.finish()
                        currentSlot.eventStream.finish()
                        self.peripheralSlots.removeValue(forKey: device.id)
                        self.enterQuarantine(for: currentSlot)
                        self.centralManager?.cancelPeripheralConnection(peripheral)
                    }
                }
    }

    private func resolvePeripheral(for external: WearfitExternalPeripheral) -> CBPeripheral? {
        #if canImport(CoreBluetooth)
        if let peripheral = external.coreBluetoothPeripheral {
            return peripheral
        }
        #endif

        if let peripheral = discoveredPeripherals[external.identifier] {
            return peripheral
        }

        let peripherals = centralManager?.retrievePeripherals(withIdentifiers: [external.identifier]) ?? []
        return peripherals.first
    }

    private func retire(_ slot: PeripheralSlot) {
        slot.timeoutTask?.cancel()
        slot.lifecycle.finish(error: WearfitBLEError.connectionSuperseded)
        slot.session?.cancelPendingCommands(reason: WearfitBLEError.connectionSuperseded)
        _ = slot.pendingConnection.resume(throwing: WearfitBLEError.connectionSuperseded)
        slot.eventStream.emit(.connectionStateChanged(.failed(
            sessionID: slot.sessionID,
            error: .connectionSuperseded
        )))
        slot.rawDataContinuation.finish()
        slot.eventStream.finish()
    }

    private func reconnectBarrier(for peripheralID: UUID) -> PeripheralReconnectBarrier {
        if let barrier = reconnectBarriers[peripheralID] {
            return barrier
        }
        let barrier = PeripheralReconnectBarrier()
        reconnectBarriers[peripheralID] = barrier
        return barrier
    }

    private func enterQuarantine(for slot: PeripheralSlot) {
        reconnectBarrier(for: slot.peripheral.identifier).enterQuarantine(
            after: slot.token,
            until: Date().addingTimeInterval(reconnectQuarantine)
        )
    }

    public func disconnect(_ device: WearfitBLEDevice) async {
        await withCheckedContinuation { continuation in
            queue.async {
                if let slot = self.peripheralSlots[device.id] {
                    self.manualDisconnectIDs.insert(device.id)
                    self.peripheralSlots.removeValue(forKey: device.id)
                    self.enterQuarantine(for: slot)
                    self.centralManager?.cancelPeripheralConnection(slot.peripheral)
                }
                continuation.resume()
            }
        }
    }

    public func executor(
        for serviceUUID: String,
        writeCharUUID: String,
        notifyCharUUID: String
    ) async throws -> BLECommandExecutor {
        throw WearfitBLEError.unsupported
    }

    private func ensurePoweredOn() async throws {
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            queue.async {
                self.ensureCentralManager()
                guard let centralManager = self.centralManager else {
                    continuation.resume(throwing: WearfitBLEError.bluetoothUnavailable)
                    return
                }
