                    self.centralManager?.stopScan()
                    self.scanContinuation?.finish(throwing: WearfitBLEError.scanTimedOut)
                    self.scanContinuation = nil
                    self.activeScanOptions = nil
                    self.logger.log(.warning, "scan timed out")
                }
            }
        }
    }
}

extension CoreBluetoothTransport: CBCentralManagerDelegate {
    public func centralManagerDidUpdateState(_ central: CBCentralManager) {
        switch central.state {
        case .poweredOn:
            logger.log(.info, "bluetooth powered on")
            eventStream.emit(.connectionStateChanged(.idle))
            centralStateContinuation?.resume()
            centralStateContinuation = nil
        case .poweredOff, .unauthorized, .unsupported:
            logger.log(.error, "bluetooth unavailable: \(central.state.rawValue)")
            for slot in peripheralSlots.values {
                slot.timeoutTask?.cancel()
                slot.lifecycle.finish(error: WearfitBLEError.bluetoothUnavailable)
                _ = slot.pendingConnection.resume(throwing: WearfitBLEError.bluetoothUnavailable)
                slot.eventStream.emit(.connectionStateChanged(.disconnected(
                    sessionID: slot.sessionID,
                    reason: .bluetoothPoweredOff
                )))
                slot.session?.cancelPendingCommands(reason: WearfitBLEError.bluetoothUnavailable)
                slot.rawDataContinuation.finish()
                slot.eventStream.finish()
            }
            peripheralSlots.removeAll()
            centralStateContinuation?.resume(throwing: WearfitBLEError.bluetoothUnavailable)
            centralStateContinuation = nil
            scanContinuation?.finish(throwing: WearfitBLEError.bluetoothUnavailable)
            scanContinuation = nil
        default:
            break
        }
    }

    public func centralManager(
        _ central: CBCentralManager,
        didDiscover peripheral: CBPeripheral,
        advertisementData: [String: Any],
        rssi RSSI: NSNumber
    ) {
        let localName = advertisementData[CBAdvertisementDataLocalNameKey] as? String
        let manufacturerData = advertisementData[CBAdvertisementDataManufacturerDataKey] as? Data
        guard let device = advertisementParser.parse(
            peripheralID: peripheral.identifier,
            peripheralName: peripheral.name,
            localName: localName,
            manufacturerData: manufacturerData,
            rssi: RSSI.intValue
        ) else {
            return
        }

        guard shouldYield(device, localName: localName, peripheralName: peripheral.name) else {
            return
        }

        discoveredPeripherals[device.id] = peripheral
        logger.log(.debug, "device discovered: \(device.name)")
        scanContinuation?.yield(device)
    }

    public func centralManager(
        _ central: CBCentralManager,
        didConnect peripheral: CBPeripheral
    ) {
        let route = reconnectBarrier(for: peripheral.identifier).routeCallback()
        if case .ignored = route {
            central.cancelPeripheralConnection(peripheral)
            return
        }
        guard case .active = route else {
            return
        }
        guard let slot = peripheralSlots[peripheral.identifier] else {
            return
        }
        let session = CoreBluetoothPeripheralSession(
            peripheral: peripheral,
            serviceConfiguration: serviceConfiguration,
            packetizer: packetizer,
            logger: logger,
            eventStream: slot.eventStream,
            rawDataContinuations: [slot.rawDataContinuation],
            queue: queue
        )
        slot.session = session
        slot.eventStream.emit(.connectionStateChanged(.connected))
        slot.eventStream.emit(.connectionStateChanged(.discoveringServices))

        Task { [weak self] in
            do {
                try await session.prepare()
                guard let self else { return }
                queue.async {
                    guard let currentSlot = self.peripheralSlots[peripheral.identifier],
                          currentSlot.token == slot.token else {
                        return
                    }
                    currentSlot.timeoutTask?.cancel()
                    currentSlot.eventStream.emit(.connectionStateChanged(.servicesReady(sessionID: currentSlot.sessionID)))
                    self.logger.log(.info, "peripheral services ready")
                    _ = currentSlot.pendingConnection.resume(returning: WearfitBLETransportSession(
                        sessionID: currentSlot.sessionID,
                        executor: session,
                        events: currentSlot.eventStream.stream,
                        rawDataStream: currentSlot.rawDataStream,
                        connectionToken: currentSlot.token,
                        lifecycle: currentSlot.lifecycle
                    ))
                }
            } catch {
                guard let self else { return }
                queue.async {
                    guard let currentSlot = self.peripheralSlots[peripheral.identifier],
                          currentSlot.token == slot.token else {
                        return
                    }
                    guard currentSlot.pendingConnection.resume(throwing: error) else {
                        return
                    }
                    currentSlot.lifecycle.finish(error: error)
                    currentSlot.eventStream.emit(.connectionStateChanged(.failed(
                        sessionID: currentSlot.sessionID,
                        error: .serviceDiscoveryFailed
                    )))
                    currentSlot.rawDataContinuation.finish()
                    currentSlot.eventStream.finish()
                    self.centralManager?.cancelPeripheralConnection(peripheral)
                    self.logger.log(.error, "peripheral preparation failed: \(error)")
                }
            }
        }
    }

    public func centralManager(
        _ central: CBCentralManager,
        didFailToConnect peripheral: CBPeripheral,
        error: Error?
    ) {
        let barrier = reconnectBarrier(for: peripheral.identifier)
        let route = barrier.routeCallback()
        guard route != .untracked, route != .ignored else {
            return
        }
        guard let slot = peripheralSlots.removeValue(forKey: peripheral.identifier) else {
            return
        }
        slot.timeoutTask?.cancel()
        slot.lifecycle.finish(error: error ?? WearfitBLEError.connectTimedOut)
        _ = slot.pendingConnection.resume(throwing: error ?? WearfitBLEError.connectTimedOut)
        logger.log(.error, "failed to connect peripheral: \(error?.localizedDescription ?? "timeout")")
        slot.eventStream.emit(.connectionStateChanged(.failed(sessionID: slot.sessionID, error: .connectTimedOut)))
        slot.rawDataContinuation.finish()
        slot.eventStream.finish()
        central.cancelPeripheralConnection(peripheral)
        enterQuarantine(for: slot)
    }

    public func centralManager(
        _ central: CBCentralManager,
        didDisconnectPeripheral peripheral: CBPeripheral,
        error: Error?
    ) {
        let barrier = reconnectBarrier(for: peripheral.identifier)
        let route = barrier.routeCallback()
        guard route != .untracked, route != .ignored else {
            return
        }
        if let slot = peripheralSlots.removeValue(forKey: peripheral.identifier) {
            slot.timeoutTask?.cancel()
            slot.timeoutTask = nil
            slot.lifecycle.finish(error: error ?? WearfitBLEError.disconnectedDuringCommand)
            slot.session?.cancelPendingCommands(reason: error ?? WearfitBLEError.disconnectedDuringCommand)
            let disconnectError: String
            if let error {
                let nsError = error as NSError
                disconnectError = "domain=\(nsError.domain) code=\(nsError.code) message=\(nsError.localizedDescription)"
            } else {
                disconnectError = "none"
            }
            logger.log(.warning, "peripheral disconnected id=\(peripheral.identifier.uuidString) error=\(disconnectError)")
            let deviceID = peripheral.identifier
            let wasManual = manualDisconnectIDs.contains(deviceID)
            _ = slot.pendingConnection.resume(
                throwing: error ?? WearfitBLEError.disconnectedDuringCommand
            )
            slot.eventStream.emit(.connectionStateChanged(.disconnected(
                sessionID: slot.sessionID,
                reason: wasManual ? .manual : .peripheralDisconnected
            )))
            slot.rawDataContinuation.finish()
            slot.eventStream.finish()
            enterQuarantine(for: slot)
            guard !wasManual else {
                manualDisconnectIDs.remove(deviceID)
                return
            }
        }
    }

    private func shouldYield(
        _ device: WearfitBLEDevice,
        localName: String?,
        peripheralName: String?
    ) -> Bool {
        guard let options = activeScanOptions else {
            return true
        }
        return [
            device.name,
            localName,
            peripheralName,
        ].compactMap { $0 }.contains(where: options.acceptsDeviceName)
            && options.acceptsDeviceMac(device.mac)
    }

    private func sessionID(for device: WearfitBLEDevice) -> WearfitSessionID {
        WearfitSessionID(device.mac ?? device.id.uuidString)
    }

    private func connectOptions(for options: WearfitConnectOptions?) -> [String: Any]? {
        var connectOptions: [String: Any] = [:]

        #if os(iOS)
        if options?.enableTransportBridging ?? true {
            if #available(iOS 13.0, *) {
                connectOptions[CBConnectPeripheralOptionEnableTransportBridgingKey] = true
            }
        }
        #endif

        return connectOptions.isEmpty ? nil : connectOptions
    }
}

// MARK: - Peripheral Command Executor

private struct PeripheralCommandExecutor: BLECommandExecutor, Sendable {
    private let session: CoreBluetoothPeripheralSession
    private let writeCharacteristic: CBCharacteristic
    private let notifyCharacteristic: CBCharacteristic

    init(
        session: CoreBluetoothPeripheralSession,
        writeCharacteristic: CBCharacteristic,
        notifyCharacteristic: CBCharacteristic
    ) {
        self.session = session
        self.writeCharacteristic = writeCharacteristic
        self.notifyCharacteristic = notifyCharacteristic
    }

    func execute(_ command: BLECommand) async throws -> Data? {
        try await session.execute(command, write: writeCharacteristic, notify: notifyCharacteristic)
    }

    func writeRaw(_ data: Data) async throws {
        try await session.writeRaw(data, to: writeCharacteristic)
    }
}
